import { evaluatePolicy } from "@moe/core";
import type { PolicySlice } from "@moe/core";
import { NODE_PROPERTY_FACT_KINDS, deriveNodePropertyFactIds } from "@moe/scheduler";
import type {
  NodeDefinition, NodePropertyFactIdsResult, NodePropertyFactKind,
} from "@moe/scheduler";

export function t1aConsumerEdgeProbe(
  definition: NodeDefinition,
  slice: PolicySlice,
): readonly string[] {
  const kinds: readonly NodePropertyFactKind[] = NODE_PROPERTY_FACT_KINDS;
  const derived: NodePropertyFactIdsResult = deriveNodePropertyFactIds(definition);
  const declared = (slice.riskClassifications ?? [])
    .map((entry) => `${entry.factId}=${entry.tier}`);
  const decided = evaluatePolicy({ sliceChain: [slice] });
  return derived.ok
    ? [...derived.factIds, ...kinds, ...declared, String(decided.ok)]
    : [...declared, ...derived.issues.map((issue) => `${issue.code}@${issue.layer}`)];
}

